# --- Constants ---
MAX_N_PER_MOTIF = 8 # Max number of 'N's allowed in a single motif to avoid memory explosion

# --- Helper function for Aho-Corasick ---
def _expand_motif_with_n(motif_template):
    """
    Expands a motif template containing 'N's into all possible concrete DNA sequences.
    E.g., "AN" -> ["AA", "AT", "AC", "AG"]
    """
    if not motif_template: # Handles empty string case
        return [""]
    
    expanded_motifs = [""] # Start with an empty string to build upon
    for char in motif_template:
        new_expanded_motifs = []
        current_bases_to_add = []
        if char.upper() == 'N':
            current_bases_to_add = ['A', 'T', 'C', 'G']
        elif char.upper() in ['A', 'T', 'C', 'G']:
            current_bases_to_add = [char.upper()]
        else:
            # Invalid character in motif template, treat as non-expandable or raise error
            # For now, let's assume motifs are pre-validated or skip expansion for invalid chars
            # This function should ideally only receive valid ATCGN motif_templates.
            # To be robust, if an invalid char is found, we might return an empty list
            # print(f"Warning: Invalid character '{char}' in motif template '{motif_template}'. Expansion might be incomplete.")
            return [] # Signal error / non-expandability for this motif

        if not current_bases_to_add: # Should not happen if motif contains only ATCGN
            return []

        for m_so_far in expanded_motifs:
            for base in current_bases_to_add:
                new_expanded_motifs.append(m_so_far + base)
        expanded_motifs = new_expanded_motifs
        
        # Safety break if expansions grow excessively (though MAX_N_PER_MOTIF should catch this earlier)
        if len(expanded_motifs) > (4**MAX_N_PER_MOTIF) * 2 : # Arbitrary safety factor
            # print(f"Warning: Expansion of '{motif_template}' is becoming too large, aborting expansion for this motif.")
            return []

    return expanded_motifs

# %% ../nbs/01_utils.ipynb 22
def get_motif_presence_in_library(short_sequences_list, left_context, right_context, flexible_motifs_df):
    """
    Creates a DataFrame indicating the presence of flexible motifs in sequences using Aho-Corasick.
    Trades memory for speed by expanding 'N's and building a multi-pattern search automaton.

    Args:
        short_sequences_list (list): List of original short DNA sequences.
        left_context (str): Left context string to prepend.
        right_context (str): Right context string to append.
        flexible_motifs_df (pd.DataFrame): DataFrame of flexible motifs, must include
                                           a 'motif' column with motif strings (e.g., 'AACNNNNCTTT').

    Returns:
        pd.DataFrame: DataFrame with full sequences (with context) as index,
                      flexible motif strings as columns, and boolean values indicating presence.
                      
    Requires:
        pyahocorasick library (pip install pyahocorasick)
    """
    # --- Input Validation ---
    if not isinstance(short_sequences_list, list):
        print("Error: short_sequences_list must be a list.")
        return pd.DataFrame()
    if not isinstance(flexible_motifs_df, pd.DataFrame) or 'motif' not in flexible_motifs_df.columns:
        print("Error: flexible_motifs_df is invalid or missing 'motif' column.")
        return pd.DataFrame()

    # --- 1. Prepare Full Sequences ---
    full_sequences_with_context = get_lib_seq_context(short_sequences_list, left_context, right_context)
    valid_full_sequences = [seq for seq in full_sequences_with_context if isinstance(seq, str)]

    if not valid_full_sequences:
        # print("No valid full sequences to process after adding context.")
        # Determine columns for empty result DataFrame
        processed_motif_columns = []
        if not flexible_motifs_df.empty:
            processed_motif_columns = flexible_motifs_df['motif'].drop_duplicates().tolist()
            processed_motif_columns = [m for m in processed_motif_columns if isinstance(m, str) and m and m.count('N') <= MAX_N_PER_MOTIF and all(c in 'ATCGN' for c in m.upper())]

        return pd.DataFrame(columns=processed_motif_columns)


    # --- 2. Prepare Motifs and Build Aho-Corasick Automaton ---
    A = ahocorasick.Automaton()
    
    # Use drop_duplicates().tolist() to get unique motifs while preserving order of first appearance
    unique_motif_templates = []
    if not flexible_motifs_df.empty:
        unique_motif_templates = flexible_motifs_df['motif'].drop_duplicates().tolist()

    # Store original motif templates that are valid and will have columns
    final_motif_columns = [] 
    
    if not unique_motif_templates:
        # print("Warning: flexible_motifs_df is empty or contains no unique motifs. Returning DataFrame with sequences but no motif columns.")
        return pd.DataFrame(index=valid_full_sequences)


    for original_motif_template in unique_motif_templates:
        if not isinstance(original_motif_template, str) or not original_motif_template:
            # print(f"Warning: Invalid motif template '{original_motif_template}' (not a string or empty). Skipping.")
            continue

        # Validate characters in motif template (allow only ATCGN)
        if not all(char.upper() in 'ATCGN' for char in original_motif_template):
            # print(f"Warning: Motif template '{original_motif_template}' contains invalid characters. Skipping.")
            continue
            
        num_n = original_motif_template.upper().count('N')
        if num_n > MAX_N_PER_MOTIF:
            print(f"Warning: Motif '{original_motif_template}' has {num_n} 'N's (max allowed: {MAX_N_PER_MOTIF}). Skipping this motif.")
            continue

        # If we reach here, the motif template is provisionally valid for processing
        current_motif_added_to_automaton = False

        # Expand and add forward motifs
        expanded_forward_literals = _expand_motif_with_n(original_motif_template)
        if not expanded_forward_literals and original_motif_template: # Check if expansion failed
             # print(f"Warning: Expansion failed for forward motif '{original_motif_template}'. Skipping.")
             continue


        for literal_motif in expanded_forward_literals:
            if literal_motif: # Ensure literal is not empty
                A.add_word(literal_motif, original_motif_template)
                current_motif_added_to_automaton = True
        
        # Expand and add reverse complement motifs
        revcomp_template = revcomp(original_motif_template)
        if revcomp_template: # revcomp might return None for invalid sequences
            # Validate characters in revcomp_template as well (should be fine if original is ATCGN)
            if not all(char.upper() in 'ATCGN' for char in revcomp_template):
                # This case should ideally not be hit if original_motif_template is valid ATCGN
                # print(f"Warning: Reverse complement template '{revcomp_template}' for '{original_motif_template}' contains invalid characters. Skipping revcomp.")
                pass # Continue, forward might still be added
            else:
                expanded_revcomp_literals = _expand_motif_with_n(revcomp_template)
                if not expanded_revcomp_literals and revcomp_template:
                    # print(f"Warning: Expansion failed for reverse complement motif '{revcomp_template}'.")
                    pass # Continue, forward might still be added

                for literal_motif in expanded_revcomp_literals:
                    if literal_motif:
                        A.add_word(literal_motif, original_motif_template)
                        current_motif_added_to_automaton = True
        
        if current_motif_added_to_automaton:
            final_motif_columns.append(original_motif_template)

    if not final_motif_columns:
        # print("No valid motifs to search for after processing flexible_motifs_df (due to format, 'N' count, or expansion issues).")
        return pd.DataFrame(index=valid_full_sequences) # Rows for sequences, no columns for motifs

    A.make_automaton()

    # --- 3. Perform Matching and Initialize Results Matrix ---
    num_sequences = len(valid_full_sequences)
    num_final_motifs = len(final_motif_columns)
    presence_matrix = np.zeros((num_sequences, num_final_motifs), dtype=bool)
    
    # Create a mapping from original motif template to its column index in the presence_matrix
    motif_to_col_idx = {motif: i for i, motif in enumerate(final_motif_columns)}

    # --- 4. Perform Matching ---
    for seq_idx, full_seq_str in enumerate(valid_full_sequences):
        # The sequence itself must be a string. Aho-Corasick expects string input.
        # Convert to uppercase for case-insensitive matching if motifs are defined as uppercase
        # Assuming sequences and motifs are consistently cased (e.g., all uppercase)
        # If not, sequences should be .upper()'d here, and motifs during expansion.
        # _expand_motif_with_n already converts motif characters to uppercase.
        
        for end_index, original_motif_found in A.iter(full_seq_str.upper()): # Search in uppercase sequence
            if original_motif_found in motif_to_col_idx: # Ensure the found motif is one we're tracking
                col_idx = motif_to_col_idx[original_motif_found]
                presence_matrix[seq_idx, col_idx] = True
            # else:
                # This case should not happen if automaton is built correctly with values from final_motif_columns
                # print(f"Debug: Motif '{original_motif_found}' found by Aho-Corasick but not in motif_to_col_idx map.")


    # --- 5. Create DataFrame from Results ---
    presence_df = pd.DataFrame(presence_matrix, index=valid_full_sequences, columns=final_motif_columns)
    presence_df.index.name = 'full_sequence'
    
    return presence_df
